css:
:scope{--ink:var(--os-color-text);--teal:#0F5457;--card:var(--os-color-surface);--rose:var(--os-color-accent);--gold:#C9A04E;--line-gold:var(--os-color-border);--serif:'Cormorant Garamond', Georgia, serif;--sans:'Jost', system-ui, sans-serif}
:scope{color:var(--ink);font-family:var(--sans);font-weight:300;font-size:18px;line-height:1.75}
@media (max-width:767px){:scope{font-size:17px}}
:where(h1,h2,h3,h4,h5,h6){color:inherit;font-family:inherit;font-weight:bold;font-style:inherit;letter-spacing:normal;text-transform:none;line-height:inherit;text-wrap:wrap}
:where(h1){font-size:2em}:where(h2){font-size:1.5em}:where(h3){font-size:1.17em}:where(h4){font-size:1em}:where(h5){font-size:.83em}:where(h6){font-size:.67em}
:where(.os-ci){display:inline-block;max-width:100%;vertical-align:middle;aspect-ratio:auto}
.os-ci>picture{display:contents}
.os-ci img{display:block;width:100%;height:100%;object-fit:inherit;object-position:inherit;border-radius:inherit}
*{box-sizing:border-box}
[class~="os-ci"]{max-width:100%;display:block}
img{display:block}
a{color:var(--teal)}
a:hover{color:var(--rose)}
h2{font-family:var(--serif);font-weight:300;margin:0;line-height:1.08;color:var(--teal)}
p{margin:0}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
.eyebrow{font-size:14px;letter-spacing:.34em;text-transform:uppercase;color:var(--rose);font-weight:400}
section{padding:100px 0}
.split{display:flex;flex-wrap:wrap;gap:64px;align-items:center}
.split > .copy{flex:1 1 400px;display:flex;flex-direction:column;gap:20px}
.arch [class~="os-ci"]{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:300px 300px 24px 24px}
.arch img{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:300px 300px 24px 24px;outline:1px solid var(--gold);outline-offset:12px}
.price-card{background:var(--card);border:1px solid var(--line-gold);border-radius:20px;padding:26px 28px;display:flex;flex-direction:column;gap:14px}
.price-row{display:flex;justify-content:space-between;gap:16px;align-items:baseline;border-bottom:1px solid #EFE4C9;padding-bottom:12px}
.price-row:last-of-type{border-bottom:0}
.price-row strong{font-family:var(--serif);font-size:30px;font-weight:500;color:var(--teal)}
.price-card small{font-size:15px;line-height:1.6;color:#4F6E70}
.form-card{background:var(--card);border:1px solid var(--line-gold);border-radius:200px 200px 28px 28px;padding:90px 40px 44px;display:flex;flex-direction:column;gap:20px}
.form-card h2{text-align:center;font-size:36px;font-weight:400}
label{display:block;font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:var(--teal);font-weight:400;margin-bottom:8px}
input,select,textarea{width:100%;font-family:var(--sans);font-size:16px;padding:15px 18px;border-radius:14px;border:1px solid #D8C49A;background:#fff;color:var(--ink)}
button{font-family:var(--sans);font-size:15px;letter-spacing:.14em;text-transform:uppercase;padding:17px 36px;border-radius:999px;border:0;background:var(--rose);color:#fff;cursor:pointer;min-height:44px}
@media (max-width:767px){section{padding:72px 0}}
@media (max-width:767px){.split{gap:44px}}
@media (max-width:767px){.form-card{padding:72px 22px 32px;border-radius:160px 160px 24px 24px}}
:scope:scope:scope .s-1{object-position:75% center}
:scope:scope:scope .s-2{max-width:440px}
:scope:scope:scope .s-3{flex:1 1 360px}
:scope:scope:scope .s-4{align-items:flex-start}
:scope:scope:scope .s-5{padding-top:30px}
